print("\n--- Validation ---")
errors = []

# Check every order line is fully picked
picked = defaultdict(int)
for (o, sku, p, r, s, t) in feasible_picks:
    val = model.getVal(q_vars[(o, sku, p, r, s, t)])
    if val > 1e-6:
        picked[(o, sku)] += val

for o in O:
    for (sku, qty) in lines[o]:
        if abs(picked.get((o, sku), 0) - qty) > 1e-4:
            errors.append(f"Order {o} SKU {sku}: picked {picked.get((o, sku), 0)}, expected {qty}")

# Check pod inventory
pod_used = defaultdict(int)
for (o, sku, p, r, s, t) in feasible_picks:
    val = model.getVal(q_vars[(o, sku, p, r, s, t)])
    if val > 1e-6:
        pod_used[(p, sku)] += val

for p in P:
    for sku in inv[p]:
        if pod_used.get((p, sku), 0) > inv[p][sku] + 1e-4:
            errors.append(f"Pod {p} SKU {sku}: used {pod_used.get((p, sku), 0)}, available {inv[p][sku]}")

# Check max split pods
for o in O:
    pods_used_o = set()
    for (o2, sku, p, r, s, t) in feasible_picks:
        if o2 == o and model.getVal(q_vars[(o, sku, p, r, s, t)]) > 1e-6:
            pods_used_o.add(p)
    if len(pods_used_o) > ord_maxsplit[o]:
        errors.append(f"Order {o}: uses {len(pods_used_o)} pods, max {ord_maxsplit[o]}")

# Check station assignment
for o in O:
    stations_o = set()
    for s in S:
        if (o, s) in z_vars and model.getVal(z_vars[(o, s)]) > 0.5:
            stations_o.add(s)
    if len(stations_o) != 1:
        errors.append(f"Order {o}: assigned to {len(stations_o)} stations")

if errors:
    print(f"VALIDATION ERRORS ({len(errors)}):")
    for e in errors[:20]:
